#!/usr/bin/env Rscript
# Reader-facing workbook of the WGCNA modules, supermodules and their labels, with everything needed to check a label:
# the rules that form it, the grouping of GO terms into signals, every significant GO term with its proteins, module
# membership with kME, and leave-one-animal-out stability. Both centrings: original (primary analysis) and complete-case
# (sensitivity analysis). Read-only for the pipeline; writes
# results/reviewer_audit/normalisation_choice_2026-10-21/workbooks/Proteomics_WGCNA_modules_and_labels.xlsx.
#
# Sources: each network's model state (both regenerated 2026-10-24/26 on the corrected code: original centring in the
# worktree Analysis/proteomics_original, complete-case in this working tree; module membership equals the earlier builds), the scripted label classes (annotation_review/rule_based/, label_modules_by_rule.R), the wording
# (rule_based/labels.tsv; supermodule labels generated by derive_supermodule_labels.R; form-checked by check_rule_labels.R),
# the change log (annotation_review/label_changes_2026-10-23.csv) and the leave-one-animal-out rebuilds
# (validation/wgcna_builds). Gene symbols are the official mouse symbols of the Entrez IDs (org.Mm.eg.db).
# USAGE  Rscript tools/normalisation_review/build_wgcna_labels_workbook.R      (working directory: repo root)

source(file.path("R", "paths.R"))
suppressPackageStartupMessages({ library(openxlsx); library(dplyr); library(readr); library(tidyr) })
source(repo_path("R", "review_workbook_style.R"))
ARCHIVE <- if (dir.exists("Q:/data")) "Q:" else
  "S:/Lab_Member/Tobi/Experiments/Exp9_Social-Stress/Analysis/_archive_proteomics_pre_renormalisation_2026-10-19"
# The original network: the original-centring regeneration on the corrected code (2026-10-24/25; worktree
# Analysis/proteomics_original, subst R:). Its membership equals the archive; module GO uses the same annotation
# and term-size limits as the complete-case network.
ORIG <- Sys.getenv("PROTEOMICS_ORIGINAL_ROOT", unset = if (dir.exists("R:/results")) "R:" else
  "S:/Lab_Member/Tobi/Experiments/Exp9_Social-Stress/Analysis/proteomics_original")
REV <- path_results("reviewer_audit", "normalisation_choice_2026-10-21")
ANN <- file.path(REV, "annotation_review"); RB <- file.path(ANN, "rule_based"); BUILDS <- file.path(REV, "validation", "wgcna_builds")
OUT <- file.path(REV, "workbooks"); dir.create(OUT, recursive = TRUE, showWarnings = FALSE)
rd <- function(f) read_csv(f, show_col_types = FALSE, guess_max = 1e5)
DATASETS <- c(neuron_neuropil = "Neuropil", neuron_soma = "Soma", microglia = "Microglia-enriched")
CENT <- c(original = "Original (primary)", new = "Complete-case (sensitivity)")
ANIMALS <- c("A0003", "A111", "A127", "A129", "A135", "A139", "A755", "A764", "A765")
STATE <- list(original = function(ds) file.path(ORIG, "results", "wgcna", "build_wgcna_modules", ds, "models", "wgcna_final_model_state.rds"),
              new = function(ds) file.path("results", "wgcna", "build_wgcna_modules", ds, "models", "wgcna_final_model_state.rds"))
EST <- c(original = "original_all_observed", new = "new_complete_case")
is_module <- function(m) !is.na(m) & !grepl("grey|unassigned|m00", m)
# gene annotation and module GO limits of a WGCNA state (states built before 2026-10-23 used the legacy annotation and 10-500)
state_evidence <- function(s) paste(s$parameters$gene_annotation_contract_version %||% "legacy_uniprot_gene_name",
                                    s$parameters$module_go_min_gs_size %||% 10L, s$parameters$module_go_max_gs_size %||% 500L, sep = " / ")
evidence_seen <- character()
short <- function(m) sub("^WGCNA_", "", m)
lab_c <- function(v) unname(CENT[v]); lab_ds <- function(d) unname(DATASETS[d])
ord <- function(df) df |> arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)))
SCI <- createStyle(numFmt = "0.0E+00", halign = "center"); D3 <- createStyle(numFmt = "0.000", halign = "center")
D1 <- createStyle(numFmt = "0.0", halign = "center"); D4 <- createStyle(numFmt = "0.0000", halign = "center"); HI <- createStyle(bgFill = "#DCEBF5", textDecoration = "bold")
sym_of <- function(entrez) {   # official mouse gene symbols
  e <- unique(na.omit(as.character(entrez))); if (!length(e)) return(setNames(character(), character()))
  suppressMessages(AnnotationDbi::mapIds(org.Mm.eg.db::org.Mm.eg.db, keys = e, column = "SYMBOL", keytype = "ENTREZID", multiVals = "first"))
}

rules <- yaml::read_yaml(file.path(RB, "rules.yml"))
rmod <- rd(file.path(RB, "module_rule_classes.csv")); rsm <- rd(file.path(RB, "supermodule_rule_classes.csv"))
rsig <- rd(file.path(RB, "module_signals.csv")); rsig_all <- rd(file.path(RB, "module_signals_all_ontologies.csv")); rterm <- rd(file.path(RB, "signal_terms.csv"))
lab <- read_tsv(file.path(RB, "labels.tsv"), show_col_types = FALSE, quote = "")
chk <- rd(file.path(RB, "label_form_check.csv")); chg <- rd(file.path(ANN, "label_changes_2026-10-23.csv"))
f3x <- rd(file.path(REV, "original_assessment", "figure3_exemplar_check.csv"))
stopifnot(nrow(lab) == nrow(chk), all(chk$problem %in% c(NA, "")))
mlab <- lab |> filter(level == "module") |> select(version, dataset, ModuleID = entity_id, label)
slab <- lab |> filter(level == "supermodule") |> select(version, dataset, SupermoduleID = entity_id, label)
sm_of <- rsm |> select(version, dataset, SupermoduleID, member_modules) |> separate_rows(member_modules, sep = ";") |> rename(ModuleID = member_modules)

# ----------------------------------------------------------------------------------- per network: state, GO, proteins, stability
ari <- function(a, b) {
  ids <- intersect(names(a), names(b)); a <- a[ids]; b <- b[ids]
  tab <- table(a, b); n <- sum(tab); c2 <- function(v) sum(v * (v - 1) / 2)
  sij <- c2(tab); sa <- c2(rowSums(tab)); sb <- c2(colSums(tab)); e <- sa * sb / (n * (n - 1) / 2)
  (sij - e) / ((sa + sb) / 2 - e)
}
jac <- function(a, b) if (!length(a) && !length(b)) NA_real_ else length(intersect(a, b)) / length(union(a, b))
stability_per_animal <- function(ds, v, long) {   # as label_modules_by_rule.R, keeping the value for each left-out animal
  prefixes <- c(if (v == "original") sprintf("%s_archived_original", ds), sprintf("%s_%s", ds, EST[[v]]))
  pipe <- setNames(ifelse(is_module(long$ModuleID), long$ModuleID, "grey"), long$ProteinGroupID)
  for (cand in prefixes) {
    f_full <- file.path(BUILDS, paste0(cand, "_full.rds")); if (!file.exists(f_full)) next
    full <- readRDS(f_full); a <- ari(full, pipe); if (a < rules$rebuild_ari) next
    map <- tibble(pg = names(full), colour = unname(full)) |> inner_join(transmute(long, pg = ProteinGroupID, ModuleID), by = "pg") |>
      filter(colour != "grey", is_module(ModuleID)) |> count(colour, ModuleID) |> group_by(colour) |> slice_max(n, n = 1, with_ties = FALSE) |> ungroup()
    files <- list.files(BUILDS, pattern = sprintf("^%s_loao_A[0-9]+[.]rds$", cand), full.names = TRUE)
    lo_all <- setNames(lapply(files, readRDS), sub("^.*_loao_(A[0-9]+)[.]rds$", "\\1", files))
    tab <- bind_rows(lapply(seq_len(nrow(map)), function(i) {
      mod_pg <- names(full)[full == map$colour[i]]
      js <- vapply(lo_all, function(lo) {
        shared <- intersect(mod_pg, names(lo)); if (!length(shared)) return(NA_real_)
        cc <- setdiff(unique(lo[shared]), "grey"); if (!length(cc)) return(0)
        max(vapply(cc, function(x) jac(shared, intersect(names(lo)[lo == x], names(full))), numeric(1)))
      }, numeric(1))
      tibble(ModuleID = map$ModuleID[i], animal = names(js), jaccard = unname(js))
    }))
    return(list(tab = tab, ari = a, source = cand))
  }
  list(tab = tibble(ModuleID = character(), animal = character(), jaccard = numeric()), ari = NA_real_, source = NA_character_)
}
nets <- list(); go_all <- list(); prot_all <- list(); stab_all <- list(); hubs_all <- list()
for (v in names(CENT)) for (ds in names(DATASETS)) {
  s <- readRDS(STATE[[v]](ds)); long <- as.data.frame(s$WGCNA_modules_long); p <- s$parameters
  evidence_seen <- unique(c(evidence_seen, state_evidence(s)))
  if (length(evidence_seen) > 1L) stop("The two networks carry different gene annotation or GO limits (", paste(evidence_seen, collapse = " vs "),
                                       "); regenerate both with the same code before comparing them.", call. = FALSE)
  go <- as.data.frame(s$GO_enrichment) |> filter(ModuleProteinSetType == "all", is_module(ModuleID))
  bg <- go |> group_by(Ontology) |> summarise(n = max(as.integer(sub("^.*/", "", BgRatio))), .groups = "drop")
  go <- go |> filter(p.adjust < rules$q)
  st <- stability_per_animal(ds, v, long)
  sym <- sym_of(long$EntrezID)
  long <- long |> mutate(entrez = as.character(EntrezID), symbol = coalesce(unname(sym[entrez]), na_if(as.character(GeneSymbol), "")))
  # hubs as the labeller takes them: the 10 highest-|kME| proteins with an Entrez ID, one per Entrez ID
  hubs <- long |> filter(is_module(ModuleID), !is.na(entrez)) |> group_by(ModuleID) |> arrange(desc(abs_kME), .by_group = TRUE) |>
    distinct(entrez, .keep_all = TRUE) |> slice_head(n = rules$hub_n) |> ungroup()
  hubs_all[[length(hubs_all) + 1L]] <- hubs |> transmute(version = v, dataset = ds, ModuleID, ProteinGroupID, entrez,
    hub_name = coalesce(symbol, as.character(RepresentativeUniProt)), labeller_name = coalesce(as.character(GeneSymbol), ""))
  nets[[length(nets) + 1L]] <- tibble(version = v, dataset = ds, samples = nrow(s$expression.data), proteins = ncol(s$expression.data),
    gene_mapped = n_distinct(long$entrez[!is.na(long$entrez)]), modules = n_distinct(long$ModuleID[is_module(long$ModuleID)]),
    supermodules = sum(rsm$version == v & rsm$dataset == ds), correlation = sprintf("%s (maxPOutliers %.2f)", p$correlation_function, p$bicor_maxPOutliers),
    network = p$network_type, rsq = p$soft_threshold_rsquared, power = s$softPower, min_size = p$min_module_size, deep_split = p$deep_split,
    merge = p$module_merge_cut_height, sm_cut = p$supermodule_merge_cut_height,
    bg_bp = bg$n[bg$Ontology == "BP"], bg_cc = bg$n[bg$Ontology == "CC"], bg_mf = bg$n[bg$Ontology == "MF"], stab_source = st$source, stab_ari = st$ari)
  symmap <- setNames(long$symbol, long$entrez)
  go_all[[length(go_all) + 1L]] <- go |> transmute(version = v, dataset = ds, ModuleID, Ontology, ID, Description, p.adjust, Count, GeneRatio, BgRatio,
    genes = vapply(strsplit(as.character(geneID), "/", fixed = TRUE), function(e) paste(coalesce(unname(symmap[e]), unname(sym[e]), e), collapse = ", "), ""))
  prot_all[[length(prot_all) + 1L]] <- long |> transmute(version = v, dataset = ds, ModuleID = ifelse(is_module(ModuleID), ModuleID, "unassigned"), ProteinGroupID,
    protein = coalesce(na_if(as.character(original_identifier), ""), na_if(as.character(RepresentativeUniProt), "")), uniprot = as.character(RepresentativeUniProt),
    gene = symbol, entrez, kME = as.numeric(kME), core = as.logical(is_core_kME_0.6), hub25 = as.logical(is_top_hub_25))
  stab_all[[length(stab_all) + 1L]] <- st$tab |> mutate(version = v, dataset = ds)
  cat(v, ds, ": modules", nets[[length(nets)]]$modules, "| GO terms", nrow(go), "| stability from", st$source, "\n")
}
nets <- bind_rows(nets); go_all <- bind_rows(go_all); prot_all <- bind_rows(prot_all); stab_all <- bind_rows(stab_all); hubs_all <- bind_rows(hubs_all)
stab_sum <- stab_all |> group_by(version, dataset, ModuleID) |>
  summarise(recovered = sum(jaccard >= rules$stable_jaccard, na.rm = TRUE), rebuilds = sum(!is.na(jaccard)), med = median(jaccard, na.rm = TRUE),
            min = min(jaccard, na.rm = TRUE), .groups = "drop")
chk_stab <- rmod |> select(version, dataset, ModuleID, stability_n_recovered, stability_median_jaccard) |> inner_join(stab_sum, by = c("version", "dataset", "ModuleID"))
stopifnot(all(chk_stab$stability_n_recovered == chk_stab$recovered), all(abs(chk_stab$stability_median_jaccard - chk_stab$med) < 1e-9))
hub_str <- hubs_all |> group_by(version, dataset, ModuleID) |> summarise(hubs = paste(hub_name, collapse = ", "), labeller = paste(labeller_name, collapse = ", "), .groups = "drop")
chk_hub <- rmod |> select(version, dataset, ModuleID, hubs) |> inner_join(hub_str, by = c("version", "dataset", "ModuleID"))
if (!all(toupper(chk_hub$hubs.x) == toupper(chk_hub$labeller)))   # same hubs as the labeller used for hub support
  stop("Hubs differ from module_rule_classes.csv: the WGCNA states are newer than the labeller output. Rerun label_modules_by_rule.R, ",
       "derive_supermodule_labels.R and check_rule_labels.R first.", call. = FALSE)

# ----------------------------------------------------------------------------------- tables
pct <- function(x) ifelse(is.na(x), NA_real_, 100 * x)
signal_of <- rterm |> group_by(version, dataset, ModuleID, ontology_set, term_id) |> summarise(signal = min(signal), .groups = "drop")
lead_ev <- rsig |> group_by(version, dataset, ModuleID) |> filter(passing) |> slice_head(n = 1) |> ungroup() |>
  transmute(version, dataset, ModuleID, lead = sprintf("%s (%s; q = %.1e; %d proteins); largest term: %s (%d proteins)", leading_term, leading_ontology, leading_q, as.integer(leading_count), best_term, as.integer(best_count)))
n_comp <- rsig |> group_by(version, dataset, ModuleID) |> summarise(n_comparable = sum(comparable), .groups = "drop")
NOTES <- tribble(~version, ~dataset, ~ModuleID, ~note,
  "original", "neuron_neuropil", "WGCNA_m15", "Keratinocyte and cornified-envelope proteins (e.g. Flg2, Sprr1b, Tgm1, Dsp) are typical of skin or handling contamination in brain tissue; not interpreted as biology.",
  "original", "microglia", "WGCNA_m09", "Keratinocyte and cornified-envelope proteins are typical of skin or handling contamination in brain tissue; not interpreted as biology.",
  "original", "microglia", "WGCNA_m04", "Labelled by its only passing signal. The module's strongest term group (synaptic vesicle cycle, presynaptic endocytosis) just misses the threshold (leading term carried by 10 proteins); 'cell cycle process' rests on general cytoskeletal and signalling proteins (e.g. Actb, Cdc42, Rhoa) and does not indicate proliferation.",
  "new", "microglia", "WGCNA_m15", "Holds most of the keratinocyte, cornified-envelope and pancreatic protease proteins of original-centring microglia m09 (e.g. Prss3b, its top member, Try10, Sprr1b, Flg2), which are typical of contamination in brain tissue; the weak label names its only GO term group.",
  "new", "neuron_neuropil", "WGCNA_m06", "Includes seven cornified-envelope proteins (cornified envelope, q = 0.013), typical of skin or handling contamination; they are not part of the label.",
  "original", "neuron_neuropil", "WGCNA_m13", "'ER stress response' is the GO term response to endoplasmic reticulum stress; it does not refer to the social-stress manipulation.",
  "new", "neuron_neuropil", "WGCNA_m11", "'ER stress response' is the GO term response to endoplasmic reticulum stress; it does not refer to the social-stress manipulation.",
  "original", "neuron_neuropil", "WGCNA_m08", "Two term groups each fall below the threshold, so the class is 'unannotated' although one is strong: aminoacyl-tRNA synthetase multienzyme complex (CC, q = 3.7e-18, 10 proteins) with tRNA aminoacylation.",
  "new", "microglia", "WGCNA_m09", "Shares its respiration signal with m16 (both led by cellular respiration; dominant-signal term sets: Jaccard 0.93) and forms the concordant supermodule SM06 with it; both carry original microglia m01's words for that signal (rule 8). Cite the module ID with the label.",
  "new", "microglia", "WGCNA_m16", "Shares its respiration signal with m09 (both led by cellular respiration; dominant-signal term sets: Jaccard 0.93) and forms the concordant supermodule SM06 with it; m16 also has a transmembrane transport signal. Cite the module ID with the label.")
changed_ids <- chg |> transmute(version, dataset, entity_id, changed = "yes")
modules <- rmod |> left_join(mlab, by = c("version", "dataset", "ModuleID")) |> left_join(sm_of, by = c("version", "dataset", "ModuleID")) |>
  left_join(lead_ev, by = c("version", "dataset", "ModuleID")) |> left_join(stab_sum, by = c("version", "dataset", "ModuleID")) |>
  left_join(n_comp, by = c("version", "dataset", "ModuleID")) |> left_join(hub_str |> select(version, dataset, ModuleID, hub_names = hubs), by = c("version", "dataset", "ModuleID")) |>
  left_join(NOTES, by = c("version", "dataset", "ModuleID")) |> left_join(changed_ids, by = c("version", "dataset", "ModuleID" = "entity_id")) |>
  ord() |>
  transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Supermodule = coalesce(SupermoduleID, ""),
    Proteins = n_proteins, `Gene-mapped proteins` = n_gene_mapped, Label = label, `Signal class` = signal_class, `Annotation confidence` = rule_confidence,
    `Comparable signals (n)` = ifelse(grepl("^unannotated", signal_class), NA_integer_, coalesce(n_comparable, 0L)),
    `Leading evidence (dominant signal)` = ifelse(grepl("^unannotated", signal_class), "", coalesce(lead, "")),
    `Dominant signal: top terms` = coalesce(dominant_signal, ""), `Second signal: top terms` = coalesce(second_signal, ""), `Third signal: top terms` = coalesce(third_signal, ""),
    `Weak association` = ifelse(nzchar(coalesce(weak_association, "")), sprintf("%s (%s; largest term %d proteins)", weak_association, weak_ontologies, as.integer(weak_size)), ""),
    `Signals grouped from` = case_when(grepl("^unannotated", signal_class) ~ "", signal_basis == "BP" ~ "BP terms", TRUE ~ "BP, CC and MF terms (no passing BP signal)"),
    `Ontologies with significant terms` = ifelse(nzchar(coalesce(module_ontologies, "")), module_ontologies, "none"),
    `Coverage (%)` = pct(coverage), `Hub support (%)` = pct(hub_support), `Hubs: top 10 gene-mapped by kME` = coalesce(hub_names, ""),
    `Stability: recovered in (of 9)` = recovered, `Stability: median Jaccard` = med, `Stability: lowest Jaccard` = min,
    `Note for readers` = coalesce(note, ""), `Label changed since 2026-10-22` = coalesce(changed, ""))
sm_members <- rsm |> separate_rows(member_modules, sep = ";") |> left_join(mlab, by = c("version", "dataset", "member_modules" = "ModuleID")) |>
  left_join(stab_sum |> select(version, dataset, member_modules = ModuleID, recovered), by = c("version", "dataset", "member_modules")) |>
  group_by(version, dataset, SupermoduleID) |>
  summarise(member_labels = paste(sprintf("%s: %s", short(member_modules), label), collapse = " || "),
            member_stab = paste(sprintf("%s %d of 9", short(member_modules), as.integer(recovered)), collapse = "; "), .groups = "drop")
supermodules <- rsm |> left_join(slab, by = c("version", "dataset", "SupermoduleID")) |> left_join(sm_members, by = c("version", "dataset", "SupermoduleID")) |>
  left_join(nets |> select(version, dataset, sm_cut), by = c("version", "dataset")) |> left_join(changed_ids, by = c("version", "dataset", "SupermoduleID" = "entity_id")) |> ord() |>
  transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Supermodule = SupermoduleID, `Member modules` = gsub(";", ", ", gsub("WGCNA_", "", member_modules)),
            Label = label, Class = rule_class, `Annotation confidence` = rule_confidence, `Members and their labels` = member_labels,
            `Members' stability (recovered in, of 9)` = member_stab,
            `Formed by` = sprintf("average-linkage clustering of module eigengenes on 1 - correlation, cut at %.2f", sm_cut), `Label changed since 2026-10-22` = coalesce(changed, ""))
sig_tab <- function(x, grouping) x |> ord() |> transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Grouping = grouping, Signal = signal,
  `Passes threshold` = ifelse(passing, "yes", "no"), `Fails because` = coalesce(fails_because, ""), `Comparable to dominant` = ifelse(comparable, "yes", ""),
  Dominant = ifelse(passing & signal == 1, "yes", ""), `Leading term` = leading_term, `Leading term: ontology` = leading_ontology, `Leading term: q` = leading_q,
  `Leading term: proteins` = leading_count, `Largest term` = best_term, `Largest term: proteins` = best_count, `Proteins in signal (all its terms)` = n_proteins,
  `Terms in signal` = n_terms, `Cellular component holding >= 50% of the signal's proteins` = coalesce(compartment, ""), `Top terms (up to 6)` = top_terms)
signals <- bind_rows(sig_tab(rsig, ifelse(rsig$ontology_set == "BP", "BP terms (classifies the module)", "BP, CC and MF terms (classifies the module; no passing BP signal)")),
                     sig_tab(rsig_all |> mutate(comparable = FALSE), "BP, CC and MF terms (decides weak or unannotated)")) |>
  arrange(factor(Centring, CENT), factor(Compartment, DATASETS), Module, Grouping, Signal)
chk_dom <- rsig |> group_by(version, dataset, ModuleID) |> summarise(ok = !any(passing) || passing[signal == 1], .groups = "drop")
stopifnot(all(chk_dom$ok))   # passing signals come first: signal 1 is the dominant one whenever any passes
go_tab <- go_all |> left_join(signal_of |> filter(!grepl("decides weak", ontology_set)) |> select(version, dataset, ModuleID, ID = term_id, sig_cls = signal), by = c("version", "dataset", "ModuleID", "ID")) |>
  left_join(signal_of |> filter(grepl("decides weak", ontology_set)) |> select(version, dataset, ModuleID, ID = term_id, sig_all = signal), by = c("version", "dataset", "ModuleID", "ID")) |>
  ord() |> group_by(version, dataset, ModuleID) |> arrange(p.adjust, desc(Count), .by_group = TRUE) |> ungroup() |>
  transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Ontology, `GO ID` = ID, Term = Description,
            `q (BH)` = p.adjust, `Module proteins with term` = Count, `Module proteins annotated in this ontology` = as.integer(sub("^.*/", "", GeneRatio)),
            `Background proteins with term` = as.integer(sub("/.*$", "", BgRatio)), `Background proteins annotated in this ontology` = as.integer(sub("^.*/", "", BgRatio)),
            `Fold enrichment` = (Count / as.integer(sub("^.*/", "", GeneRatio))) / (as.integer(sub("/.*$", "", BgRatio)) / as.integer(sub("^.*/", "", BgRatio))),
            `In signal (classifying grouping)` = sig_cls, `In signal (weak/unannotated grouping)` = sig_all, `Proteins (gene symbols)` = genes)
hub_flag <- hubs_all |> transmute(version, dataset, ProteinGroupID, is_hub = TRUE)
proteins <- prot_all |> left_join(sm_of, by = c("version", "dataset", "ModuleID")) |> left_join(hub_flag, by = c("version", "dataset", "ProteinGroupID")) |>
  arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)), ModuleID == "unassigned", ModuleID, desc(kME)) |>
  transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), Supermodule = coalesce(SupermoduleID, ""),
            Protein = coalesce(protein, "(no UniProt entry)"), UniProt = coalesce(uniprot, ""), Gene = coalesce(gene, ""), `Entrez ID` = coalesce(entrez, ""),
            `Gene-mapped (has Entrez ID)` = ifelse(nzchar(coalesce(entrez, "")), "yes", ""), `kME (own module)` = kME,
            `Hub for hub support (top 10)` = ifelse(is_hub %in% TRUE, "yes", ""), `Core (kME >= 0.6)` = ifelse(core %in% TRUE, "yes", ""),
            `Top-25 hub (network-build flag, not used here)` = ifelse(hub25 %in% TRUE, "yes", ""))
stability <- stab_all |> mutate(animal = factor(animal, ANIMALS)) |> arrange(animal) |>
  pivot_wider(names_from = animal, values_from = jaccard, names_prefix = "without ") |>
  left_join(stab_sum, by = c("version", "dataset", "ModuleID")) |> ord() |> arrange(factor(version, names(CENT)), factor(dataset, names(DATASETS)), ModuleID) |>
  transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Module = short(ModuleID), across(starts_with("without ")),
            `Recovered in (of 9)` = recovered, `Median Jaccard` = med, `Lowest Jaccard` = min)
