n_of <- function(v, what) sum(modules$Centring == lab_c(v) & modules$`Signal class` == what)
cnt <- function(v) sprintf("%s: %d modules (single signal %d, two signals %d, several signals %d, unannotated (weak) %d, unannotated %d) and %d supermodules in the three compartments.",
                           lab_c(v), sum(modules$Centring == lab_c(v)), n_of(v, "single signal"), n_of(v, "two signals"), n_of(v, "several signals"),
                           n_of(v, "unannotated (weak)"), n_of(v, "unannotated"), sum(supermodules$Centring == lab_c(v)))
example <- function(cls, conf = NULL) {   # first module of the primary centring with that class (and confidence)
  x <- rmod |> filter(version == "original", signal_class == cls, is.null(conf) | rule_confidence %in% conf) |> left_join(mlab, by = c("version", "dataset", "ModuleID")) |>
    left_join(lead_ev, by = c("version", "dataset", "ModuleID")) |> arrange(factor(dataset, names(DATASETS)), ModuleID) |> slice(1)
  if (!nrow(x)) return(NULL)
  why <- if (cls == "unannotated (weak)") paste0("one term group over BP, CC and MF, which does not pass the threshold (terms: ", gsub(" [|] ", ", ", x$weak_association), "); the label names its most specific term (rule 7)")
         else if (cls == "unannotated") "no term group passes the threshold, and the module has none or more than one sub-threshold group" else coalesce(x$lead, "")
  sprintf("%s %s: %s. Class %s, annotation confidence %s%s. Label: '%s'.", lab_ds(x$dataset), short(x$ModuleID), why, cls, x$rule_confidence,
          if (is.na(x$coverage)) "" else sprintf(" (coverage %.0f%%, hub support %.0f%%)", 100 * x$coverage, 100 * x$hub_support), x$label)
}
ex <- Filter(Negate(is.null), list(example("single signal", "high"), example("single signal", c("moderate", "low")), example("two signals"), example("several signals"),
                                   example("unannotated (weak)"), example("unannotated")))
rule_lines <- c(
  sprintf("1. Evidence. When each network was built, the proteins of every module were tested for over-representation of GO terms (BP, CC and MF) against all proteins of the compartment that carry an annotation in that ontology (the background; sheet Networks), with Benjamini-Hochberg correction. Terms with q < %.2f are significant (sheet GO evidence). A protein counts as gene-mapped when it has an Entrez Gene ID; only gene-mapped proteins can carry GO terms.", rules$q),
  sprintf("2. Term groups. The %d most significant BP terms of a module (ordered by q) are clustered by the proteins they share: overlap coefficient |A and B| / min(|A|, |B|) between the module proteins of two terms, average linkage, tree cut at 1 - %.1f (the EnrichmentMap default). Nested terms (a complex and its subunit, a process and its regulation) therefore fall into one group.", rules$top_terms, rules$overlap),
  sprintf("3. Merging groups into signals. Within a group the leading term is the most significant (ties: more proteins) and the largest term the one with most proteins (ties: the more significant). Groups are taken in order of the size of their largest term (ties: the more significant leading term first). Each group whose proteins overlap an earlier kept group with overlap coefficient >= %.1f is merged into the first such group; otherwise it is kept as a new signal. A merged signal keeps the most significant term as its leading term and the term with most proteins as its largest term. Then passing signals (rule 4) of which at least %.0f%% of the proteins each lie in the same significant CC term of the module (among its %d most significant CC terms) are merged into one signal, and that cellular component is recorded (for example respiration and ATP synthesis in the mitochondrial inner membrane).",
          rules$overlap, 100 * rules$overlap, rules$top_terms),
  sprintf("4. Threshold. A signal passes when (a) the module has significant terms in at least %d of the three ontologies and (b) the signal's leading term (most significant; ties: the term with more proteins) is carried by more than %d module proteins. A signal that fails (a) or (b) is sub-threshold (sheet Signals, column Fails because). A module without a passing BP signal is grouped again over all three ontologies (BP, CC and MF, rules 2 and 3); if that grouping has a passing signal, it classifies the module (a location- or complex-defined module).", rules$min_ontologies, rules$min_proteins),
  sprintf("5. Signal class. The dominant signal is the passing signal with the largest largest-term (ties: the more significant leading term). Every passing signal whose largest term has at least %.0f%% of the dominant one's proteins is comparable. single signal = no other comparable signal; two signals = one other; several signals = two or more others. Without a passing signal, the module's significant terms are grouped over all three ontologies: exactly one group gives 'unannotated (weak)', none or more than one gives 'unannotated'.", 100 * rules$comparable_ratio),
  sprintf("6. Annotation confidence (how well GO describes the module, not how robust the module is; see Stability). Coverage = proteins in the dominant signal's largest term / gene-mapped module proteins. Hub support = share of the module's %d highest-|kME| gene-mapped proteins (one per gene) that carry any term of the dominant signal. single signal: high when coverage >= %.0f%% and hub support >= %.0f%%; moderate when coverage >= %.0f%%, or when the dominant signal contains a term with at least %d module proteins that holds at least %.0f%% of that term's background proteins (a complex); otherwise low. two signals: moderate by the same coverage or complex rule, otherwise low. several signals and unannotated (weak): low. unannotated: none.",
          rules$hub_n, 100 * rules$high_cov, 100 * rules$hub_share, 100 * rules$mod_cov, rules$complex_n, 100 * rules$complex_share),
  "7. Module wording (written by hand, checked mechanically against rules 5 and 6). single signal: 'X-enriched' at high confidence, 'X-associated' otherwise. two signals: 'X- and Y-associated'. several signals: 'Several signals: X, Y, Z', naming the three largest comparable signals. weak: 'unannotated (weak X association)'. unannotated: 'unannotated'. X is a short form of a GO term of that signal: its leading or largest term; when these are broad parent terms (for example 'secretion', 'generation of precursor metabolites and energy'), the signal's most specific characteristic term, and the signal's cellular component may qualify it ('mitochondrial respiration'). '/' joins further terms of the same signal when one term alone would misdescribe it (for example 'RNA processing/splicing'). Every named term can be found under that signal in sheet GO evidence. A weak association is named the same way from its term group. Shortened terms keep their meaning ('regulation of' stays regulation; a process is not renamed after a structure), and term words are not hyphenated beyond GO's own spelling. 'enriched' and 'associated' refer to the signal as a whole (coverage of its largest term), not to the named term alone. Within one network (one compartment under one centring) no two labels are the same, except 'unannotated' and members of a concordant supermodule whose dominant signals coincide (cite the module ID with such a label).",
  sprintf("8. Same words across centrings. A complete-case module whose main source is one original-centring module (at least %.0f%% of its proteins) carries that module's words for the shared dominant signal when its own GO shows that signal (the original module's leading term is among its comparable signals' terms, or their term sets have Jaccard >= %.1f); its other signals are named from its own GO. Module numbers are not comparable between centrings.", 100 * rules$carry_share, rules$term_jaccard),
  sprintf("9. Supermodules. Modules whose eigengenes are correlated are joined by average-linkage clustering on 1 - eigengene correlation, cut per compartment (sheet Networks). Classes: singleton (one member; weak or unannotated members keep their class), unannotated (several members, none labelled), mixed (labelled and unlabelled members), concordant (all labelled, and every pair of members' dominant-signal term sets has Jaccard >= %.1f), compound (all labelled, otherwise). Labels are generated from the members' labels: a member contributes its own wording without the suffix; a two-signal member 'X and Y'; a several-signal member its first two signals, 'X and Y' ('/' joins only terms of one signal). singleton (member of any class): the member's label with its ID, 'X-enriched (m05)', 'Several signals: X, Y, Z (m05)', 'unannotated (weak X association; m05)', 'unannotated (m05)'; concordant: 'X-enriched (m09 + m16)'; compound: 'Compound: X (mA) + Y (mB)'; mixed: 'Mixed: X (mA) + unannotated member (mB)'; unannotated: 'unannotated (weak X (mA) and Y (mB) associations)'. Annotation confidence: singleton = the member's; concordant and compound = the lowest member's; mixed = low; unannotated = low when a member is weak, otherwise none.", rules$term_jaccard),
  sprintf("10. Stability (reported next to a label, never in it). Each network was rebuilt 9 times with its own parameters, each time without one animal; the rebuilds are used only when the same procedure on all animals reproduces the network (adjusted Rand index >= %.2f). A module is recovered in a rebuild when its best-matching module there has Jaccard >= %.1f (sheet Stability).", rules$rebuild_ari, rules$stable_jaccard),
  "11. What labels do not claim. A label names what a module's proteins have in common in GO. It does not claim a demonstrated function, a cell type of origin, a response to stress, or causality. Proteins measured in microglia-enriched regions need not come from microglia. Labels were formed without any group, behaviour or physiology result.")
