# ----------------------------------------------------------------------------------- workbook
text_sheet <- function(wb, sheet, title, blocks) {   # same layout as the Read me sheet
  addWorksheet(wb, sheet); r <- 1
  writeData(wb, sheet, title, startRow = r); addStyle(wb, sheet, TITLE, rows = r, cols = 1); r <- r + 2
  body <- createStyle(fontName = "Arial", fontSize = 11, wrapText = TRUE, valign = "top")
  for (b in blocks) {
    writeData(wb, sheet, b$heading, startRow = r); addStyle(wb, sheet, SUB, rows = r, cols = 1); r <- r + 1
    writeData(wb, sheet, data.frame(x = b$lines), startRow = r, colNames = FALSE)
    addStyle(wb, sheet, body, rows = r:(r + length(b$lines) - 1), cols = 1, gridExpand = TRUE); r <- r + length(b$lines) + 1
  }
  setColWidths(wb, sheet, cols = 1, widths = 150); showGridLines(wb, sheet, FALSE)
}
put <- function(sheet, df, widths, freeze = 4, ints = character(), d1 = character(), d2 = character(), d3 = character(), d4 = character(), sci = character(), wrap = character(), centre = character()) {
  ci <- function(nm) match(nm, names(df))
  put_table(wb, sheet, df, int_cols = ci(ints), n2_cols = ci(d2), left_cols = which(!names(df) %in% c(ints, d1, d2, d3, d4, sci, centre)), widths = widths, freeze_col = freeze)
  rows <- 2:(nrow(df) + 1)
  if (length(d1)) addStyle(wb, sheet, D1, rows = rows, cols = ci(d1), gridExpand = TRUE, stack = TRUE)
  if (length(d3)) addStyle(wb, sheet, D3, rows = rows, cols = ci(d3), gridExpand = TRUE, stack = TRUE)
  if (length(d4)) addStyle(wb, sheet, D4, rows = rows, cols = ci(d4), gridExpand = TRUE, stack = TRUE)
  if (length(sci)) addStyle(wb, sheet, SCI, rows = rows, cols = ci(sci), gridExpand = TRUE, stack = TRUE)
  if (length(wrap)) addStyle(wb, sheet, WRAP, rows = rows, cols = ci(wrap), gridExpand = TRUE, stack = TRUE)
}
