  list(heading = "What this file is", lines = c(
    "Every co-abundance module and supermodule of the WGCNA networks of the three compartments (neuropil, soma, microglia-enriched regions), with its label and everything needed to check how the label was reached: the rules, the grouping of GO terms into signals, every significant GO term with its proteins, module membership with kME, and the stability of each module when one animal is left out.",
    "Two centrings, each with its own network per compartment. Primary analysis: each sample centred on the median of all its observed proteins (original centring). Sensitivity analysis: each sample centred on the median of the proteins quantified in every sample of the compartment (complete-case centring). Each network was built on its own and labelled from its own GO evidence; where a complete-case module continues an original one, it keeps the original's words for the shared signal (rule 8). Module numbers are not comparable between the centrings (sheet Correspondence shows how modules overlap). The neuropil networks differ by one sample: the original-centring build removed one sample as an outlier (sheet Networks).",
    cnt("original"), cnt("new"))),
  list(heading = "How the networks were built", lines = c(
    "Samples are bilateral (left and right hemisphere) laser-microdissected region-layer units of 9 male mice (3 control, 3 resilient, 3 susceptible). Per compartment: signed adjacency from biweight midcorrelation (maxPOutliers 0.05) at the soft power reaching scale-free fit R^2 >= 0.8; topological overlap (TOM); average-linkage clustering of 1 - TOM; dynamic hybrid tree cut (deep split 2, minimum module size 30) whose PAM stage assigns every protein to its closest module, so no protein is left unassigned; modules with eigengene correlation >= 0.75 merged (cut height 0.25). Parameters per network: sheet Networks.",
    "Gene mapping: GO testing uses proteins with an Entrez Gene ID from the official mouse annotation used by the differential-abundance analysis (org.Mm.eg.db, accession first; groups of several genes stay unannotated), and GO terms with 10 to 800 background proteins. Both networks were regenerated with this mapping on 2026-10-24/26; module membership did not change, the GO evidence and therefore some labels did (sheet Label corrections).")),
  list(heading = "Sheets", lines = c(
    "How labels are formed: the rules, thresholds and wording templates, with worked examples.",
    "Networks: how each network was built and which rebuilds the stability uses.",
    "Modules and Supermodules: one row each, with label, class, annotation confidence, the evidence behind it and stability.",
    "Signals: how each module's significant GO terms were grouped into signals, which signal is dominant, and why a signal does not pass.",
    "GO evidence: every significant GO term (q < 0.05) of every module, with its signal and the module proteins that carry it.",
    "Proteins: module membership of every protein with its kME, and the hubs used for hub support.",
    "Stability: each module's Jaccard similarity to its best match in each of the 9 leave-one-animal-out rebuilds.",
    "Correspondence: modules of the two centrings that share at least 20% of either module's proteins.",
    "Label corrections: labels that changed since 2026-10-22 (after a check of every label against its evidence, and with the regeneration of 2026-10-25/26), with the previous wording and the reason.",
    "Figure 3 modules: the modules shown with the three exemplar GO terms of Figure 3 and how they were chosen.",
    "Columns: what each column means.")),
  list(heading = "How to check a label", lines = c(
    "1. Find the module in sheet Modules (filter Centring and Compartment). Leading evidence and Dominant signal give the terms the label is named after; Coverage and Hub support give its annotation confidence.",
    "2. In sheet Signals, filter the module: every signal with its leading and largest term, whether it passes the threshold and why not, and which is dominant or comparable. This shows why the label names one, two or several signals, or none. Modules without any significant GO term (Ontologies: none) have no rows there.",
    "3. In sheet GO evidence, filter the module: every significant term with its q value, its signal and the proteins that carry it.",
    "4. In sheet Proteins, filter the module: its proteins ordered by kME; the hubs used for hub support are flagged.",
    "5. Sheet Stability shows whether the module is recovered when each animal is left out. Stability and group or phenotype results do not enter the label.")),
  list(heading = "Provenance", lines = c(
    "Networks: the saved WGCNA networks, both regenerated on the corrected code (original centring 2026-10-24/25 in the worktree Analysis/proteomics_original, with module membership identical to the hash-verified archive of 2026-10-19; complete-case 2026-10-25/26 in the current analysis). Classes: tools/normalisation_review/label_modules_by_rule.R. Wording: annotation_review/rule_based/labels.tsv (module labels by hand; supermodule labels generated by tools/normalisation_review/derive_supermodule_labels.R), all labels pass the mechanical form check (tools/normalisation_review/check_rule_labels.R). This workbook: tools/normalisation_review/build_wgcna_labels_workbook.R; nothing in it was edited by hand."))))
text_sheet(wb, "How labels are formed", "How a module label is formed", list(
  list(heading = "Rules (the same code and thresholds for every module of both centrings)", lines = rule_lines),
  list(heading = "Thresholds", lines = c(
    sprintf("GO significance q < %.2f; term groups from the %d most significant BP terms (or BP, CC and MF terms); grouping cut: overlap coefficient %.1f; merging: overlap coefficient >= %.1f, cellular-component merge: >= %.0f%% of each signal's proteins in one CC term; passing: significant terms in >= %d ontologies and leading term > %d module proteins; comparable: >= %.0f%% of the dominant signal's largest term; high confidence: coverage >= %.0f%% and hub support >= %.0f%% of %d hubs; moderate: coverage >= %.0f%%, or a term with >= %d module proteins holding >= %.0f%% of its background proteins; same words across centrings: >= %.0f%% shared proteins and term Jaccard >= %.1f; concordant supermodule: term Jaccard >= %.1f; stability: Jaccard >= %.1f in rebuilds reproducing the network at adjusted Rand index >= %.2f.",
            rules$q, rules$top_terms, rules$overlap, rules$overlap, 100 * rules$overlap, rules$min_ontologies, rules$min_proteins, 100 * rules$comparable_ratio,
            100 * rules$high_cov, 100 * rules$hub_share, rules$hub_n, 100 * rules$mod_cov, rules$complex_n, 100 * rules$complex_share,
            100 * rules$carry_share, rules$term_jaccard, rules$term_jaccard, rules$stable_jaccard, rules$rebuild_ari))),
  list(heading = "Worked examples (primary centring)", lines = unlist(ex))))
netsheet <- nets |> ord() |> transmute(Centring = lab_c(version), Compartment = lab_ds(dataset), Samples = samples,
  `Samples: note` = case_when(dataset == "neuron_neuropil" & version == "original" ~ "9 animals x 10 region-layer units x 2 hemispheres = 180; one sample (A135, left CA1 stratum oriens) removed by the build's sample-outlier filter",
                              dataset == "neuron_neuropil" ~ "9 animals x 10 region-layer units x 2 hemispheres",
                              dataset == "neuron_soma" ~ "9 animals x 4 regions x 2 hemispheres = 72; one failed acquisition excluded",
                              TRUE ~ "9 animals x 4 regions x 2 hemispheres"),
  Proteins = proteins, `Gene-mapped proteins` = gene_mapped, Modules = modules, Supermodules = supermodules, Adjacency = sprintf("%s, %s", network, correlation),
  `Soft power` = power, `Scale-free fit target (R^2)` = rsq, `Minimum module size` = min_size, `Deep split` = deep_split, `Module merge cut height` = merge,
  `Supermodule cut height` = sm_cut, `GO background BP` = bg_bp, `GO background CC` = bg_cc, `GO background MF` = bg_mf,
  `Stability rebuilds` = ifelse(grepl("archived", stab_source), "rebuilt with the network's parameters from its archived input data (179 samples)", "rebuilt with the network's parameters from its input data"),
  `Rebuild with all animals vs network (adjusted Rand index)` = stab_ari)
put("Networks", netsheet, widths = c(26, 18, 9, 50, 9, 11, 9, 12, 30, 8, 11, 10, 8, 10, 11, 10, 10, 10, 30, 14), freeze = 3,
    ints = c("Samples", "Proteins", "Gene-mapped proteins", "Modules", "Supermodules", "Soft power", "Minimum module size", "Deep split", "GO background BP", "GO background CC", "GO background MF"),
    d3 = "Rebuild with all animals vs network (adjusted Rand index)", d2 = c("Scale-free fit target (R^2)", "Module merge cut height", "Supermodule cut height"), wrap = c("Samples: note", "Stability rebuilds"))
put("Modules", modules, widths = c(26, 18, 8, 11, 9, 10, 50, 14, 11, 10, 60, 60, 44, 36, 40, 22, 12, 10, 10, 44, 11, 11, 11, 60, 11),
    ints = c("Proteins", "Gene-mapped proteins", "Comparable signals (n)", "Stability: recovered in (of 9)"), d1 = c("Coverage (%)", "Hub support (%)"),
    d3 = c("Stability: median Jaccard", "Stability: lowest Jaccard"), wrap = c("Label", "Leading evidence (dominant signal)", "Dominant signal: top terms", "Second signal: top terms",
    "Third signal: top terms", "Weak association", "Hubs: top 10 gene-mapped by kME", "Note for readers"))
put("Supermodules", supermodules, widths = c(26, 18, 11, 20, 60, 16, 11, 80, 30, 50, 11), wrap = c("Label", "Members and their labels", "Members' stability (recovered in, of 9)", "Formed by"))
put("Signals", signals, widths = c(26, 18, 8, 34, 7, 9, 34, 11, 9, 40, 9, 10, 9, 40, 9, 11, 9, 30, 80),
    ints = c("Signal", "Leading term: proteins", "Largest term: proteins", "Proteins in signal (all its terms)", "Terms in signal"), sci = "Leading term: q",
    wrap = c("Grouping", "Fails because", "Leading term", "Largest term", "Top terms (up to 6)"))
put("GO evidence", go_tab, widths = c(26, 18, 8, 8, 12, 50, 10, 10, 12, 11, 12, 9, 10, 12, 100),
    ints = c("Module proteins with term", "Module proteins annotated in this ontology", "Background proteins with term", "Background proteins annotated in this ontology",
             "In signal (classifying grouping)", "In signal (weak/unannotated grouping)"), d1 = "Fold enrichment", sci = "q (BH)", centre = "Ontology")
put("Proteins", proteins, widths = c(26, 18, 8, 11, 22, 12, 12, 11, 11, 10, 11, 9, 13), d4 = "kME (own module)")
put("Stability", stability, widths = c(26, 18, 8, rep(9, 9), 10, 10, 10), freeze = 4, ints = "Recovered in (of 9)",
