conditionalFormatting(wb, "Stability", cols = sc, rows = 2:(nrow(stability) + 1), rule = sprintf(">=%s", rules$stable_jaccard), style = HI)
put("Correspondence", corr, widths = c(18, 12, 50, 12, 50, 10, 12, 12, 9), freeze = 3, ints = "Shared proteins", d1 = c("Share of original module (%)", "Share of complete-case module (%)"),
    d3 = "Jaccard", wrap = c("Original label", "Complete-case label"))
put("Label corrections", changes, widths = c(26, 18, 12, 9, 50, 50, 90), freeze = 5, wrap = c("Label until 2026-10-22", "Current label", "Why"))
put("Figure 3 modules", fig3, widths = c(18, 26, 30, 30, 8, 50, 11, 12, 11, 11, 50, 90), freeze = 5, ints = "Stability: recovered in (of 9)", d1 = "Exemplar term: fold enrichment",
    sci = "Exemplar term: q in module", centre = "Exemplar term: module proteins", wrap = c("Exemplar GO term", "Region of the exemplar (Figure 3)", "Label", "How the module was chosen", "Note for readers"))
